import{_ as s,o as i,c as l,a3 as c,j as e,a as r}from"./chunks/framework.z_KJ15Ep.js";const h="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-bei-schuelern-loeschen.png",_=JSON.parse('{"title":"Einzelne Fächer bei einer Schülergruppe löschen","description":"","frontmatter":{"title":"Einzelne Fächer bei einer Schülergruppe löschen","source_pageid":300,"source_revision":5345},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/einzelne-faecher-bei-schuelern-loeschen-gruppenprozesse-faecher.md","filePath":"schild3/suchen-gruppenprozesse/einzelne-faecher-bei-schuelern-loeschen-gruppenprozesse-faecher.md"}'),t={name:"schild3/suchen-gruppenprozesse/einzelne-faecher-bei-schuelern-loeschen-gruppenprozesse-faecher.md"};function p(a,n,u,o,d,g){return i(),l("div",null,[...n[0]||(n[0]=[c('<h1 id="einzelne-facher-bei-einer-schulergruppe-loschen" tabindex="-1">Einzelne Fächer bei einer Schülergruppe löschen <a class="header-anchor" href="#einzelne-facher-bei-einer-schulergruppe-loschen" aria-label="Permalink to &quot;Einzelne Fächer bei einer Schülergruppe löschen&quot;">​</a></h1><p>Entfernen Sie ausgewählte Unterrichtsfächer im angegebenen Schuljahr und Abschnitt. Über eine zusätzliche Option können kursgebundene Einträge geschützt werden.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-bei-schuelern-loeschen.png"><img src="'+h+'" alt="Gruppenprozesse_Fächer_bei_SchülerInnen_löschen" loading="lazy"></a></p><p><em>Gruppenprozesse_Fächer_bei_SchülerInnen_löschen</em></p><p>Wählen Sie zuerst die gewünschte Schülergruppe aus. Öffnen Sie dann <strong>Gruppenprozesse ➜ Fächer ➜ Einzelne Fächer bei Schülern löschen</strong>.</p><p>Dieser Gruppenprozess ermöglicht das Löschen ganzer Unterrichtsfächer im jeweils ausgewählten Schuljahr und Abschnitt bei der selektierten Schülergruppe.</p><p>Das Häkchen, das ganz unten gesetzt werden kann, verhindert das versehentliche Löschen von Fächern, in denen Kurse zugewiesen sind. Ist das Häkchen gesetzt, werden nur Fächer ohne Kurseintrag gelöscht.</p>',7),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),r("Beispiel")]),e("p",null,"Dies kann notwendig sein, wenn wegen Veränderungen in der Unterrichtsverteilung Unterricht komplett entfällt."),e("p",null,"Ein weiterer Anwendungsfall wäre es, über eine Stundentafel jeweils allen Schülern eines Jahrgangs die epochal unterrichteten Fächer zuzuweisen und dann bei der jeweils zutreffenden Gruppe das nicht belegte Fach zu löschen.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Einzelne_F%C3%A4cher_bei_Sch%C3%BClern_l%C3%B6schen_(Gruppenprozesse_F%C3%A4cher)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),r(" · Quellrevision 5345.")],-1)])])}const f=s(t,[["render",p]]);export{_ as __pageData,f as default};
